import { describe, it, expect, beforeAll } from 'vitest'
import { readFileSync } from 'fs'
import { resolve } from 'path'
import { slugify, getQuestionId } from '../../app/composables/useSlugify'

/**
 * FAQ Internal Links Verification Tests
 * 
 * These tests ensure all internal links in content/faqs.md are valid.
 * Internal links must match the IDs generated by the FAQ accordion component.
 * 
 * This test should be run whenever FAQ content is modified to catch broken links.
 * 
 * Both faqs.vue and FaqAccordion now use the useSlugify composable with 150 char limit.
 * 
 * Link format: [Link Text](#section-slug-question-slug)
 * ID generation: getQuestionId(sectionHeading, questionText) from useSlugify composable
 */

interface FaqSection {
  heading: string
  slug: string
  questions: Array<{
    text: string
    id: string
  }>
}

describe('FAQ Internal Links', () => {
  let faqContent: string
  let sections: FaqSection[]
  let allQuestionIds: Set<string>
  let internalLinks: string[]

  beforeAll(() => {
    // Read the FAQ markdown file
    const faqPath = resolve(__dirname, '../../content/faqs.md')
    faqContent = readFileSync(faqPath, 'utf-8')
    
    // Parse sections (H2 headings) and questions (H3 headings)
    sections = parseFaqStructure(faqContent)
    
    // Build a set of all valid question IDs
    allQuestionIds = new Set<string>()
    
    // Add section IDs (H2 headings can be linked to)
    for (const section of sections) {
      allQuestionIds.add(section.slug)
      for (const question of section.questions) {
        allQuestionIds.add(question.id)
      }
    }
    
    // Also add special IDs that exist (like glossary, main-content)
    allQuestionIds.add('glossary')
    allQuestionIds.add('main-content')
    
    // Extract all internal links from the markdown
    internalLinks = extractInternalLinks(faqContent)
  })

  /**
   * Parse the FAQ markdown structure to extract sections and questions
   * Uses slugify (150 char limit) from useSlugify composable
   */
  function parseFaqStructure(content: string): FaqSection[] {
    const lines = content.split('\n')
    const result: FaqSection[] = []
    let currentSection: FaqSection | null = null

    for (const line of lines) {
      // Match H2 headings (sections)
      const h2Match = line.match(/^## (.+)$/)
      if (h2Match) {
        const heading = h2Match[1].trim()
        currentSection = {
          heading,
          slug: slugify(heading), // 150 char limit from useSlugify composable
          questions: []
        }
        result.push(currentSection)
        continue
      }

      // Match H3 headings (questions)
      const h3Match = line.match(/^### (.+)$/)
      if (h3Match && currentSection) {
        const questionText = h3Match[1].trim()
        const questionId = getQuestionId(currentSection.heading, questionText)
        currentSection.questions.push({
          text: questionText,
          id: questionId
        })
      }
    }

    return result
  }

  /**
   * Extract all internal links from markdown content
   * Matches: [text](#anchor-id)
   */
  function extractInternalLinks(content: string): string[] {
    const linkPattern = /\]\(#([a-z0-9-]+)\)/g
    const links: string[] = []
    let match

    while ((match = linkPattern.exec(content)) !== null) {
      links.push(match[1])
    }

    return links
  }

  it('should have parsed FAQ structure correctly', () => {
    expect(sections.length).toBeGreaterThan(0)
    expect(allQuestionIds.size).toBeGreaterThan(0)
  })

  it('should have found internal links to verify', () => {
    expect(internalLinks.length).toBeGreaterThan(0)
  })

  it('should have all internal links pointing to valid targets', () => {
    const brokenLinks: Array<{ link: string, suggestion?: string }> = []

    for (const link of internalLinks) {
      if (!allQuestionIds.has(link)) {
        // Try to find a similar ID for suggestion
        const suggestion = findSimilarId(link, allQuestionIds)
        brokenLinks.push({ link, suggestion })
      }
    }

    if (brokenLinks.length > 0) {
      const errorMessage = brokenLinks.map(({ link, suggestion }) => {
        let msg = `  ❌ #${link}`
        if (suggestion) {
          msg += `\n     Did you mean: #${suggestion}?`
        }
        return msg
      }).join('\n')

      expect.fail(
        `Found ${brokenLinks.length} broken internal link(s):\n${errorMessage}\n\n` +
        `To fix: Update the links in content/faqs.md to match the generated IDs.\n` +
        `IDs are generated using: getQuestionId(sectionHeading, questionText) from useSlugify.ts`
      )
    }

    expect(brokenLinks).toHaveLength(0)
  })

  it('should verify each link individually', () => {
    // This test provides detailed output for each link
    const results = internalLinks.map(link => ({
      link,
      valid: allQuestionIds.has(link)
    }))

    const validCount = results.filter(r => r.valid).length
    const totalCount = results.length

    console.log(`\n📋 Internal Link Verification: ${validCount}/${totalCount} valid`)
    
    expect(validCount).toBe(totalCount)
  })

  /**
   * Find a similar ID from the set (for suggestions when a link is broken)
   */
  function findSimilarId(brokenLink: string, validIds: Set<string>): string | undefined {
    // Extract key parts of the broken link for matching
    const parts = brokenLink.split('-')
    const keyParts = parts.slice(-4).join('-') // Last 4 parts often contain the question

    for (const validId of validIds) {
      // Check if the valid ID ends similarly
      if (validId.includes(keyParts)) {
        return validId
      }
      // Check Levenshtein-like similarity (simple version)
      if (validId.includes(parts.slice(-3).join('-'))) {
        return validId
      }
    }

    return undefined
  }

  describe('Link target verification', () => {
    it('should have unique question IDs (no collisions)', () => {
      const idCounts = new Map<string, number>()
      
      for (const section of sections) {
        for (const question of section.questions) {
          const count = idCounts.get(question.id) || 0
          idCounts.set(question.id, count + 1)
        }
      }

      const duplicates = Array.from(idCounts.entries())
        .filter(([, count]) => count > 1)
        .map(([id]) => id)

      if (duplicates.length > 0) {
        expect.fail(
          `Found duplicate question IDs (will cause link issues):\n` +
          duplicates.map(id => `  - ${id}`).join('\n')
        )
      }

      expect(duplicates).toHaveLength(0)
    })

    it('should not have excessively long IDs that might be truncated', () => {
      const longIds: string[] = []
      const MAX_SAFE_LENGTH = 150

      for (const section of sections) {
        for (const question of section.questions) {
          if (question.id.length >= MAX_SAFE_LENGTH) {
            longIds.push(`${question.id} (${question.id.length} chars)`)
          }
        }
      }

      if (longIds.length > 0) {
        console.warn(
          `⚠️ Found IDs at or near max length (${MAX_SAFE_LENGTH} chars):\n` +
          longIds.map(id => `  - ${id}`).join('\n')
        )
      }

      // This is a warning, not a failure - the slugify handles truncation
      expect(true).toBe(true)
    })
  })

  describe('Section coverage', () => {
    it('should have all major sections represented', () => {
      const sectionHeadings = sections.map(s => s.heading)
      
      // Expected major sections
      const expectedSections = [
        'Quick Start',
        'Getting Started',
        'Website Accessibility',
        'Content Accessibility',
        'Compliance Requirements'
      ]

      for (const expected of expectedSections) {
        const found = sectionHeadings.some(h => 
          h.toLowerCase().includes(expected.toLowerCase())
        )
        expect(found, `Missing section containing: ${expected}`).toBe(true)
      }
    })
  })
})

/**
 * Export test utilities for potential reuse
 */
export { slugify, getQuestionId }

